pub fn has_test_cfg(module_def_hir: hir::ModuleDef, db: &ide::RootDatabase) -> bool {
    let key = hir::Symbol::intern("test");
    let attrs = match module_def_hir {
        hir::ModuleDef::Module(r#mod) => r#mod.attrs(db),
        hir::ModuleDef::Function(r#fn) => r#fn.attrs(db),
        hir::ModuleDef::Adt(adt) => adt.attrs(db),
        hir::ModuleDef::EnumVariant(r#variant) => r#variant.attrs(db),
        hir::ModuleDef::Const(r#const) => r#const.attrs(db),
        hir::ModuleDef::Static(r#static) => r#static.attrs(db),
        hir::ModuleDef::Trait(r#trait) => r#trait.attrs(db),
        hir::ModuleDef::TraitAlias(trait_type) => trait_type.attrs(db),
        hir::ModuleDef::TypeAlias(type_alias) => type_alias.attrs(db),
        hir::ModuleDef::BuiltinType(_builtin_type) => return false,
        hir::ModuleDef::Macro(_) => return false,
    };

    attrs.cfgs(db).is_some()
}

